package com.sumitdocmind;
import javax.crypto.Mac; import javax.crypto.spec.SecretKeySpec; import java.nio.charset.StandardCharsets; import java.util.Base64;
import org.springframework.stereotype.Component;
@Component public class JwtUtil { private final String secret; public JwtUtil(org.springframework.core.env.Environment e){secret=e.getProperty("app.jwt-secret","local-dev-secret-change-this-to-a-long-random-string");} private String sign(String data){try{Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8),"HmacSHA256"));return Base64.getUrlEncoder().withoutPadding().encodeToString(m.doFinal(data.getBytes(StandardCharsets.UTF_8)));}catch(Exception x){throw new RuntimeException(x);}} public String issue(long uid){String h=Base64.getUrlEncoder().withoutPadding().encodeToString("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8));String p=Base64.getUrlEncoder().withoutPadding().encodeToString(("{\"sub\":\""+uid+"\",\"exp\":\""+(System.currentTimeMillis()+86400000)+"\"}").getBytes(StandardCharsets.UTF_8));String body=h+"."+p;return body+"."+sign(body);} public Long verify(String token){try{String[] a=token.split("\\.");if(a.length!=3||!sign(a[0]+"."+a[1]).equals(a[2]))return null;String p=new String(Base64.getUrlDecoder().decode(a[1]),StandardCharsets.UTF_8);String s=p.replaceAll(".*\\\"sub\\\":\\\"([0-9]+)\\\".*","$1");String ex=p.replaceAll(".*\\\"exp\\\":\\\"([0-9]+)\\\".*","$1");long uid=Long.parseLong(s);if(System.currentTimeMillis()>Long.parseLong(ex))return null;return uid;}catch(Exception e){return null;}} }
